#include <bits/stdc++.h>
#define int long long
using namespace std;
int OP,n,m,D,q;
int a[500005];
vector<pair<int,int> > vc[500005];
int dis[505][505];
signed main(){
	freopen("subway.in","r",stdin);
	freopen("subway.out","w",stdout);
	scanf("%lld%lld%lld%lld%lld",&OP,&n,&m,&D,&q);
	for(int i=1;i<=m;++i) scanf("%lld",&a[i]);
	for(int i=1;i<=n;++i){
		int c,x,y;
		scanf("%lld",&c);
		while(c--){
			scanf("%lld%lld",&x,&y);
			vc[x].push_back(make_pair(i,y));
		}
	}
	for(int i=1;i<=n;++i)
		for(int j=1;j<=n;++j)
			if(i!=j) dis[i][j]=0x3f3f3f3f3f3f3f3f;
	for(int i=1;i<=m;++i){
		for(int j=0;j<(int)vc[i].size();++j)
			for(int k=j+1;k<(int)vc[i].size();++k){
				int x=vc[i][j].first,y=vc[i][k].first;
				dis[x][y]=dis[y][x]=min(dis[x][y],vc[i][j].second+vc[i][k].second);
			}
	}
	for(int k=1;k<=n;++k)
		for(int i=1;i<=n;++i)
			for(int j=1;j<=n;++j) dis[i][j]=min(dis[i][j],dis[i][k]+dis[k][j]);
	while(q--){
		int x,y;
		scanf("%lld%lld",&x,&y);
		int ans=0x3f3f3f3f3f3f3f3f;
		for(auto u:vc[x])
			for(auto v:vc[y]){
				ans=min(ans,u.second+v.second+dis[u.first][v.first]);
			}
		printf("%lld\n",ans+a[x]+a[y]);
	}
	return 0;
}
